<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit;
require dirname(__DIR__).'/vendor/autoload.php';
use ReGen\{Config,ManagedRealtime,RealtimeEvents};
Config::load(dirname(__DIR__));
if(!in_array(Config::get('app.env'),['development','test','testing'],true)||!in_array(Config::get('db.host'),['localhost','127.0.0.1','::1'],true))throw new RuntimeException('Local development database required.');
$connect=static fn(?string $name=null):PDO=>new PDO('mysql:host='.Config::get('db.host').';port='.Config::get('db.port').($name?';dbname='.$name:'').';charset=utf8mb4',Config::get('db.user'),Config::get('db.password'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
$server=$connect();$name='regen_managed_test_'.bin2hex(random_bytes(6));$server->exec('CREATE DATABASE `'.$name.'` CHARACTER SET utf8mb4');$count=0;$db=null;
$settings=new ReflectionProperty(Config::class,'values');$original=$settings->getValue();
$check=static function(bool $ok,string $message)use(&$count):void{$count++;if(!$ok)throw new RuntimeException($message);};
$denied=static function(callable $action,string $message)use($check):void{try{$action();}catch(DomainException){$check(true,$message);return;}$check(false,$message);};
try{
    $db=$connect($name);$db->exec(file_get_contents(dirname(__DIR__).'/database/schema.sql'));
    $settings->setValue(null,array_replace($original,['realtime.transport'=>'auto','realtime.pusher_app_id'=>'1234','realtime.pusher_key'=>'fixture-key','realtime.pusher_secret'=>'fixture-secret','realtime.pusher_cluster'=>'ap1']));
    $user=['role'=>'user','id'=>7,'topics'=>['notifications','support']];$admin=['role'=>'admin','id'=>2,'topics'=>['support','alerts','profile']];
    $check(ManagedRealtime::configured(),'Complete provider configuration enables managed delivery.');
    $auth=ManagedRealtime::authorize($user,'private-regen-user-account-7','123.456');
    $check($auth['auth']==='fixture-key:'.hash_hmac('sha256','123.456:private-regen-user-account-7','fixture-secret'),'Official SDK signs the private subscription correctly.');
    $denied(fn()=>ManagedRealtime::authorize($user,'private-regen-user-account-8','123.456'),'Users cannot authorize another account channel.');
    $denied(fn()=>ManagedRealtime::authorize($user,'private-regen-admin-support','123.456'),'User sessions cannot authorize administrator channels.');
    $denied(fn()=>ManagedRealtime::authorize($admin,'private-regen-admin-users','123.456'),'Delegated administrators cannot subscribe to unassigned modules.');
    $denied(fn()=>ManagedRealtime::authorize($admin,'private-regen-admin-account-3','123.456'),'Administrators cannot authorize another private alert channel.');
    $denied(fn()=>ManagedRealtime::authorize($user,'private-regen-users',"123.456\nforged"),'Malformed socket IDs must be rejected.');
    $check(isset(ManagedRealtime::authorize($admin,'private-regen-admin-support','123.456')['auth']),'Assigned module subscriptions are authorized.');
    $public=json_encode(ManagedRealtime::publicConfiguration($user));$check(!str_contains($public,'fixture-secret')&&!str_contains($public,'1234'),'Only the public app key and allowed channel names reach the browser.');
    $events=new RealtimeEvents($db);$calls=[];
    $delivery=new ManagedRealtime($db,static function(array $channels,string $event,array $data)use(&$calls):void{$calls[]=[$channels,$event,$data];});
    for($index=0;$index<1000;$index++)$events->publish('support','user',7,$index+1);$events->dispatch();
    $check($delivery->flush()===1000&&count($calls)===1,'A thousand events on one channel coalesce into one provider request.');
    $check($calls[0]=== [['private-regen-user-account-7'],'wake',['changed'=>true]],'Managed payloads contain no resource IDs, topics, private content or credentials.');
    $check($delivery->flush()===0&&count($calls)===1,'Delivered journal ranges must not be sent twice.');
    $db->beginTransaction();$events->publish('support','user',7);$check($delivery->flush()===0,'Uncommitted changes cannot be published.');$db->rollBack();$events->dispatch();$check($delivery->flush()===0,'Rollback cannot generate provider notifications.');
    $events->publish('maintenance','users');$events->dispatch();$attempts=0;
    $failed=new ManagedRealtime($db,static function()use(&$attempts):void{$attempts++;throw new RuntimeException('simulated provider outage');});
    $cursor=(int)$db->query('SELECT delivered_cursor FROM realtime_delivery_state WHERE id=1')->fetchColumn();
    $check($failed->flush()===0,'Provider failure leaves the application data committed.');
    $check((int)$db->query('SELECT delivered_cursor FROM realtime_delivery_state WHERE id=1')->fetchColumn()===$cursor,'Failure must retain the durable delivery checkpoint.');
    $failed->flush();$check($attempts===1,'The shared circuit breaker prevents an outage from delaying every request.');
    $db->exec('UPDATE realtime_delivery_state SET retry_at=UTC_TIMESTAMP()-INTERVAL 1 SECOND WHERE id=1');
    $events->dispatch();$check($delivery->flush()>=1,'Pending signals recover after the backoff.');
    $check((int)$db->query("SELECT COUNT(*) FROM security_incidents WHERE title='Live delivery needs attention'")->fetchColumn()===1,'The first provider failure creates one operational incident.');
    for($index=1;$index<=205;$index++)$events->publish('notifications','user',$index);$events->dispatch();$before=count($calls);$sent=0;
    do{$batch=$delivery->flush();$sent+=$batch;}while($batch);
    $check($sent===205&&count($calls)-$before===3,'Large recipient sets publish in bounded batches without skipping users.');
    $check(max(array_map(static fn(array $call):int=>count($call[0]),$calls))<=100,'Provider requests must respect the channel limit.');
    $settings->setValue(null,array_replace($settings->getValue(),['realtime.transport'=>'poll']));
    $check(!ManagedRealtime::configured()&&ManagedRealtime::publicConfiguration($user)===null,'Explicit fallback mode disables external connections.');
    echo "Managed private-channel authorization, batching, outage isolation and durable retries passed ($count assertions; isolated database, mocked provider).\n";
}finally{$settings->setValue(null,$original);if($db&&$db->inTransaction())$db->rollBack();$server->exec('DROP DATABASE `'.$name.'`');}
